import java.util.*;
import java.util.function.Supplier;

public class Main {
    static int fails = 0;

    static void check(String name, List<Integer> coins, int total, List<Integer> expected) {
        try {
            ChangeCalculator cc = new ChangeCalculator(coins);
            List<Integer> got = cc.computeMostEfficientChange(total);
            if (!got.equals(expected)) {
                System.out.println("FAIL " + name + ": expected " + expected + " got " + got);
                fails++;
            } else {
                System.out.println("ok   " + name + " -> " + got);
            }
        } catch (Throwable t) {
            System.out.println("FAIL " + name + ": unexpected " + t);
            fails++;
        }
    }

    static void checkThrows(String name, List<Integer> coins, int total, String msg) {
        try {
            new ChangeCalculator(coins).computeMostEfficientChange(total);
            System.out.println("FAIL " + name + ": no exception");
            fails++;
        } catch (IllegalArgumentException e) {
            if (!msg.equals(e.getMessage())) {
                System.out.println("FAIL " + name + ": msg expected '" + msg + "' got '" + e.getMessage() + "'");
                fails++;
            } else {
                System.out.println("ok   " + name + " -> threw '" + e.getMessage() + "'");
            }
        } catch (Throwable t) {
            System.out.println("FAIL " + name + ": wrong exception " + t);
            fails++;
        }
    }

    public static void main(String[] a) {
        check("1cent", Arrays.asList(1,5,10,25), 1, Arrays.asList(1));
        check("singleCoin", Arrays.asList(1,5,10,25,100), 25, Arrays.asList(25));
        check("multiple", Arrays.asList(1,5,10,25,100), 15, Arrays.asList(5,10));
        check("40cents", Arrays.asList(1,5,10,25,100), 40, Arrays.asList(5,10,25));
        check("lilliputian", Arrays.asList(1,4,15,20,50), 23, Arrays.asList(4,4,15));
        check("lowerElbonian", Arrays.asList(1,5,10,21,25), 63, Arrays.asList(21,21,21));
        check("large999", Arrays.asList(1,2,5,10,20,50,100), 999,
              Arrays.asList(2,2,5,20,20,50,100,100,100,100,100,100,100,100,100));
        check("noUnitCoin", Arrays.asList(2,5,10,20,50), 21, Arrays.asList(2,2,2,5,10));
        check("anotherNoUnit", Arrays.asList(4,5), 27, Arrays.asList(4,4,4,5,5,5));
        check("greedyNotOptimal", Arrays.asList(1,10,11), 20, Arrays.asList(10,10));
        check("zero", Arrays.asList(1,5,10,21,25), 0, new ArrayList<Integer>());
        checkThrows("lessThanSmallest", Arrays.asList(5,10), 3, "The total 3 cannot be represented in the given currency.");
        checkThrows("largerUnrepresentable", Arrays.asList(5,10), 94, "The total 94 cannot be represented in the given currency.");
        checkThrows("negative", Arrays.asList(1,2,5), -5, "Negative totals are not allowed.");
        // extra semantic checks
        checkThrows("emptyCurrencyWithTotal", new ArrayList<Integer>(), 5, "The total 5 cannot be represented in the given currency.");
        check("emptyCurrencyZero", new ArrayList<Integer>(), 0, new ArrayList<Integer>());
        check("unsortedInput", Arrays.asList(25,100,1,10,5), 40, Arrays.asList(5,10,25));
        check("largeCoinAboveTotal", Arrays.asList(1,1000), 7, Arrays.asList(1,1,1,1,1,1,1));
        System.out.println(fails == 0 ? "ALL EDGE CHECKS PASSED" : (fails + " FAILURES"));
    }
}
